import ast
for p in ["supply_guard/osv.py","supply_guard/catalog.py"]:
    src=open(p).read(); tree=ast.parse(src)
    imported=[]
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            for a in n.names: imported.append((a.asname or a.name).split(".")[0])
        elif isinstance(n,ast.ImportFrom):
            for a in n.names: imported.append(a.asname or a.name)
    used={x.id for x in ast.walk(tree) if isinstance(x,ast.Name)}
    unused=[i for i in imported if i not in used and i!="annotations"]
    print(p, "unused:", unused)
EOF
